const cmd = `$env:Path='C:\\Windows\\System32;'+$env:Path
$ua='Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/155.0.0.0 Safari/537.36'
$t=@(
 'https://arctic-shift.photon-reddit.com/api/posts/search?subreddit=college&query=tutor&limit=5',
 'https://arctic-shift.photon-reddit.com/api/posts/search?subreddit=sidehustle&limit=5',
 'https://api.pullpush.io/reddit/search/submission/?subreddit=college&q=tutor&size=5'
)
foreach($u in $t){
  $code = curl.exe -s -o "$env:TEMP\\rr.json" -w "%{http_code} %{size_download}" -x http://127.0.0.1:7897 -H "User-Agent: $ua" --max-time 25 --compressed $u
  Write-Output "=== $code  $u"
  Get-Content "$env:TEMP\\rr.json" -Raw -ErrorAction SilentlyContinue | Select-Object -First 1 | ForEach-Object { $_.Substring(0,[Math]::Min(400,$_.Length)) }
}
`;
const r = await tools.pwsh({ description: "Test ArcticShift and pullpush APIs", command: cmd, timeoutMs: 180000 });
console.log(r.kind === 'foreground' ? r.stdout.text + "|ERR:" + r.stderr.text : JSON.stringify(r));
